// Value: protects=the big screen's dish line names the dish, says who ate it in a room and never on the boss, and a page
// opened on a served dish shows the dish at once (cooking I1, I3); fails_when=a dishLine branch swaps or a hook's first
// frame replays the cooking; why_new=e2e checks the dish card only and never opens a page after 上菜; seam=none;
// no_claim=the timed frames and callbacks (useEffect does not run in renderToStaticMarkup; e2e covers them)
import { describe, expect, it, vi } from "vitest";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { DishOnStage, dishLine, dishUp, EAT_STEP_AT, useCookStep, useFinaleStep, useRevealTime } from "@/components/cooking";
import { COOK_MS, EAT_MS, SERVE_HOLD_MS } from "@/lib/protocol";
import { Sprite } from "@/components/pixel";
import { PHONE_LAG_MS, revealBeats, revealNow } from "@/lib/podium";
import type { MonsterSprite, SpriteKind } from "@/lib/sprite-kind";

const dish = { name: "史萊姆凍", part: "外膜", method: "冰鎮", comment: "冰冰涼涼。", points: 10, monster: { name: "史萊姆", sprite: "slime" as const, hue: 0 }, room: 0, teamId: "t1" };

describe("dishLine", () => {
  it("names the dish, the team and its 飽足感 in a room; only the dish without a team or on the boss", () => {
    expect(dishLine(dish, "紅隊", false)).toBe("今晚的菜：史萊姆凍！紅隊吃下 10 飽足感。");
    expect(dishLine(dish, "", false)).toBe("今晚的菜：史萊姆凍！");
    expect(dishLine(dish, "紅隊", true)).toBe("今晚的大菜：史萊姆凍！");
  });
});

/** The hook's first frame, as a page that has just opened sees it. */
const first = (hook: () => unknown) => renderToStaticMarkup(createElement(() => String(hook())));

describe("the first cooking frame (cooking I3, R8)", () => {
  it("useCookStep: nothing before 上菜, the dish at once on a page opened after it", () => {
    expect(first(() => useCookStep(null))).toBe("null");
    expect(first(() => useCookStep("7"))).toBe("7"); // the end of the meal: the empty plate (eat-dish.md)
  });

  it("useFinaleStep: a boss kill seen live starts on the monster, a page opened on the end screen goes to the podium", () => {
    expect(first(() => useFinaleStep(true))).toBe("0");
    expect(first(() => useFinaleStep(false))).toBe("4");
  });
});

// Value: protects=a page older than the server draws an unknown monster sprite as a slime and its dish as the slime's dish,
// instead of crashing the render (monster-catalog.md Rollout 5); fails_when=the Object.hasOwn guard in Sprite or DishOnStage
// is dropped or swapped for `in` (an inherited key like "toString"); why_new=PR2 tested only monsterLook, not the components;
// seam=none; no_claim=the canvas pixels (useEffect does not run in renderToStaticMarkup)
describe("a sprite this page does not know (a newer server)", () => {
  const html = (el: Parameters<typeof renderToStaticMarkup>[0]) => renderToStaticMarkup(el);
  const unknown = ["not-yet-drawn", "toString"] as unknown as SpriteKind[];

  it("Sprite draws it in the slime's box", () => {
    const slime = html(createElement(Sprite, { kind: "slime", scale: 2 }));
    expect(slime).toContain("width:64px;height:60px");
    for (const kind of unknown) expect(html(createElement(Sprite, { kind, scale: 2 }))).toBe(slime);
  });

  it("DishOnStage serves the slime's dish", () => {
    const served = (sprite: string) => html(createElement(DishOnStage, { dish: { ...dish, monster: { ...dish.monster, sprite: sprite as MonsterSprite } }, cardTop: 0, bottom: 0 }));
    for (const kind of unknown) expect(served(kind)).toBe(served("slime"));
  });
});

// Value: protects=the screen and the phone open on the room's clock: a page that opens mid-reveal starts at the beat
// the room is on, the phone PHONE_LAG_MS behind, and a page with no reveal shows the end (podium-reveal.md D7, D16,
// eng D20, D23); fails_when=a page starts its own clock at 0 (replaying the reveal), the lag is dropped so a phone
// shows the winner with or before the screen, or an older server's STATE hangs on 名次揭曉中…; why_new=new;
// seam=none; no_claim=the timers moving the beat on (useEffect does not run here; e2e main-line covers the phone)
describe("the podium reveal's first frame", () => {
  // The places only: the two 🛡️ titles before them would only shift every time here.
  const beats = revealBeats([{ id: "a", name: "甲" }, { id: "b", name: "乙" }], ["a", "b"], []).filter((b) => b.kind !== "award");
  /** "beat result done" as the page's first frame sees it. */
  const show = (n: { beat: number; result: boolean; done: boolean }) => `${n.beat} ${n.result} ${n.done}`;
  const at = (elapsedMs: number, lag = 0, b: typeof beats | null = beats) =>
    first(() => show(revealNow({ beats: b }, useRevealTime({ ranking: ["a", "b"], beats: b, elapsedMs }, lag))));

  it("a page opened mid-reveal is on the room's beat, not the first one", () => {
    expect(at(4000)).toBe("1 true false");
    expect(at(-500)).toBe("-1 false false");
  });

  it("the phone is still waiting when the screen puts first place up", () => {
    expect(at(3500)).toBe("1 true false");
    expect(at(3500, PHONE_LAG_MS)).toBe("0 false false");
    expect(at(3500 + PHONE_LAG_MS, PHONE_LAG_MS)).toBe("1 true false");
  });

  it("waits while the lines are coming; with no reveal at all it is the end", () => {
    expect(at(0, 0, null)).toBe("-1 false false");
    expect(first(() => show(revealNow(undefined, useRevealTime(undefined))))).toBe("-1 true true");
  });

  // Value: protects=reduced motion shows the big screen the end at once, but a phone still waits for the room's clock, so it
  // never names the winner before the screen (podium-reveal.md D16, /review D25-1); fails_when=the phone's clock honors
  // reduced motion again; why_new=iOS Reduce Motion spoiled first place and then hid the story; seam=matchMedia stub;
  // no_claim=the phone's later STATEs (the gate follows `up` both ways, e2e main-line)
  it("under reduced motion the screen shows the end, the phone keeps waiting", () => {
    vi.stubGlobal("matchMedia", () => ({ matches: true }));
    try {
      const view = (motionOnly: boolean) =>
        first(() => show(revealNow({ beats }, useRevealTime({ ranking: ["a", "b"], beats, elapsedMs: 3500 }, motionOnly ? 0 : PHONE_LAG_MS, motionOnly))));
      expect(view(true)).toBe("-1 true true");
      expect(view(false)).toBe("0 false false");
    } finally {
      vi.unstubAllGlobals();
    }
  });
});

// Value: protects=the team eats the dish in three 400 ms bites a second after it is up, the empty plate comes before 下一題
// unlocks, and every eating step keeps the dish on stage (the five `=== 3` spots); the eater shows only when its team is
// still in the room (docs/designs/eat-dish.md); fails_when=a step's time drifts, SERVE_HOLD_MS undercuts the meal, dishUp
// drops a step, or the eater/plate render on the wrong step; why_new=new feature; seam=none; no_claim=the timers firing
// and the bitten pixels (useEffect does not run in renderToStaticMarkup; biteCells is tested in lib/pixel-art.test.ts)
describe("eating the dish (eat-dish.md)", () => {
  it("bites at 2.6, 3.0, 3.4 s, the empty plate at 3.8 s, and 下一題 a second later", () => {
    expect(EAT_STEP_AT).toEqual([[4, 2600], [5, 3000], [6, 3400], [7, 3800]]);
    expect(EAT_MS).toBe(3800);
    expect(SERVE_HOLD_MS).toBe(4800);
    expect(EAT_STEP_AT[0][1]).toBeGreaterThan(COOK_MS);
  });

  it("the dish stays up from step 3 to the empty plate", () => {
    expect([null, 0, 1, 2, 3, 4, 5, 6, 7].map((s) => dishUp(s as Parameters<typeof dishUp>[0]))).toEqual([false, false, false, false, true, true, true, true, true]);
  });

  const at = (step: 3 | 4 | 5 | 6 | 7, eater = 2) => renderToStaticMarkup(createElement(DishOnStage, { dish, cardTop: 0, bottom: 146, step, eater }));
  it("the eater comes on at the first bite, chews on 5 and 6, and the plate is empty at 7 with the dish's scale", () => {
    expect(at(3)).not.toContain("width:96px;height:96px");
    expect(at(4)).toContain("啊嗚！");
    expect(at(5)).toContain("嚼嚼");
    expect(at(5)).toContain("px-tf2");
    const end = at(7);
    expect(end).toContain("嗝～");
    expect(end).toContain("width:96px;height:96px"); // the hero at scale 4
    expect(end).toContain("width:170px;height:60px"); // the 34×12 plate at the jelly's scale 5
    expect(end).toContain("data-step=\"7\"");
  });

  it("a team gone before the meal leaves no eater, no hearts, no 嗝", () => {
    const end = at(7, -1);
    expect(end).not.toContain("width:96px;height:96px");
    expect(end).not.toContain("嗝～");
    expect(end).toContain("width:170px;height:60px");
  });
});
